package com.company.platform.order;
import com.company.platform.order.domain.*;import org.junit.jupiter.api.Test;import java.math.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class OrderDomainTest{@Test void orderRequiresItemBeforeSubmit(){var o=Order.create(UUID.randomUUID(),new OrderNumber("ORD-1"),UUID.randomUUID(),UUID.randomUUID(),Currency.getInstance("USD"));assertThrows(IllegalStateException.class,o::submit);}@Test void lifecycleAndSubtotalAreConsistent(){var o=Order.create(UUID.randomUUID(),new OrderNumber("ORD-2"),UUID.randomUUID(),UUID.randomUUID(),Currency.getInstance("USD"));o.addItem(new OrderItem(null,o.id(),UUID.randomUUID(),"Widget",2,new Money(new BigDecimal("3.50"),Currency.getInstance("USD")),null));assertEquals(new BigDecimal("7.00"),o.subtotal().amount());o.submit();o.confirm();assertEquals(OrderStatus.CONFIRMED,o.status());o.cancel();assertEquals(OrderStatus.CANCELLED,o.status());}@Test void tenantIsRequired(){assertThrows(IllegalArgumentException.class,()->Order.create(null,new OrderNumber("ORD-3"),UUID.randomUUID(),UUID.randomUUID(),Currency.getInstance("USD")));}}
